alter table public.profiles add column if not exists gender text check (gender in ('male','female'));
update public.profiles set username=coalesce(username, lower(regexp_replace(coalesce(display_name,'uye')||'_'||substr(id::text,1,6),'[^a-zA-Z0-9_]+','','g'))) where username is null;
create unique index if not exists profiles_username_lower_idx on public.profiles(lower(username));

alter table public.categories add column if not exists topic_count integer not null default 0;
