create table if not exists public.topics(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete restrict,category_id uuid not null references public.categories(id),title text not null check(char_length(title) between 8 and 180),body text not null check(char_length(body) between 20 and 10000),slug text unique not null,audience text not null default 'all' check(audience in ('all','male','female')),is_anonymous boolean not null default false,status text not null default 'pending' check(status in ('pending','published','rejected','hidden','deleted')),view_count integer not null default 0 check(view_count>=0),answer_count integer not null default 0 check(answer_count>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.answers(id uuid primary key default gen_random_uuid(),topic_id uuid not null references public.topics(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete restrict,body text not null check(char_length(body) between 2 and 5000),is_anonymous boolean not null default false,is_best_answer boolean not null default false,useful_count integer not null default 0 check(useful_count>=0),status text not null default 'pending' check(status in ('pending','published','rejected','hidden','deleted')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.topics add column if not exists moderation_note text,add column if not exists moderated_by uuid references public.profiles(id) on delete set null,add column if not exists moderated_at timestamptz;
alter table public.answers add column if not exists moderation_note text,add column if not exists moderated_by uuid references public.profiles(id) on delete set null,add column if not exists moderated_at timestamptz;
alter table public.topics alter column status set default 'pending';alter table public.answers alter column status set default 'pending';
create unique index if not exists one_best_answer_per_topic on public.answers(topic_id) where is_best_answer;
create table if not exists public.answer_votes(answer_id uuid not null references public.answers(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(answer_id,user_id));
create table if not exists public.topic_bookmarks(topic_id uuid not null references public.topics(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(topic_id,user_id));
alter table public.reports drop constraint if exists reports_target_type_check;alter table public.reports add constraint reports_target_type_check check(target_type in('story','comment','user','topic','answer'));
alter table public.reports drop constraint if exists reports_reason_check;alter table public.reports add constraint reports_reason_check check(reason in('hakaret','taciz','nefret_soylemi','spam','yaniltici_icerik','kisisel_bilgi','diger','siddet','yanlis_bilgi','mustehcen'));

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,username,display_name,avatar_url,gender) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1)||'_'||substr(new.id::text,1,6)),coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)),new.raw_user_meta_data->>'avatar_url',nullif(new.raw_user_meta_data->>'gender',''));return new;end;$$;
-- Admin ve moderator rollerini RLS icinde guvenle kontrol eder.
-- 001_admin_panel.sql yalnizca is_admin/is_moderator tanimladigi icin gereken ortak ad burada eklenir.
create or replace function public.is_staff()
returns boolean language sql stable security definer
set search_path=public as $$
  select exists(
    select 1 from public.profiles
    where id=auth.uid() and role in ('admin','moderator')
  );
$$;
revoke all on function public.is_staff() from public;
grant execute on function public.is_staff() to anon,authenticated;
create or replace function public.sync_answer_count() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' and new.status='published' then update topics set answer_count=answer_count+1 where id=new.topic_id;elsif tg_op='DELETE' and old.status='published' then update topics set answer_count=greatest(answer_count-1,0) where id=old.topic_id;elsif tg_op='UPDATE' and old.status is distinct from new.status then if new.status='published' then update topics set answer_count=answer_count+1 where id=new.topic_id;elsif old.status='published' then update topics set answer_count=greatest(answer_count-1,0) where id=old.topic_id;end if;end if;return null;end;$$;
create or replace function public.sync_vote_count() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then update answers set useful_count=useful_count+1 where id=new.answer_id;else update answers set useful_count=greatest(useful_count-1,0) where id=old.answer_id;end if;return null;end;$$;
drop trigger if exists answers_count on public.answers;create trigger answers_count after insert or update of status or delete on public.answers for each row execute function public.sync_answer_count();drop trigger if exists votes_count on public.answer_votes;create trigger votes_count after insert or delete on public.answer_votes for each row execute function public.sync_vote_count();
create or replace function public.choose_best_answer(answer_uuid uuid) returns void language plpgsql security definer set search_path=public as $$declare topic_uuid uuid;begin select a.topic_id into topic_uuid from answers a join topics t on t.id=a.topic_id where a.id=answer_uuid and t.user_id=auth.uid();if topic_uuid is null then raise exception 'Not allowed';end if;update answers set is_best_answer=false where topic_id=topic_uuid;update answers set is_best_answer=true where id=answer_uuid;end;$$;revoke all on function public.choose_best_answer(uuid) from public;grant execute on function public.choose_best_answer(uuid) to authenticated;

alter table public.topics enable row level security;alter table public.answers enable row level security;alter table public.answer_votes enable row level security;alter table public.topic_bookmarks enable row level security;
drop policy if exists topics_read on public.topics;drop policy if exists topics_insert on public.topics;drop policy if exists topics_update on public.topics;
drop policy if exists answers_read on public.answers;drop policy if exists answers_insert_audience on public.answers;drop policy if exists answers_update on public.answers;
drop policy if exists votes_read on public.answer_votes;drop policy if exists votes_insert on public.answer_votes;drop policy if exists votes_delete on public.answer_votes;
drop policy if exists bookmarks_own_read on public.topic_bookmarks;drop policy if exists bookmarks_own_insert on public.topic_bookmarks;drop policy if exists bookmarks_own_delete on public.topic_bookmarks;
create policy topics_read on public.topics for select using(status='published' or user_id=auth.uid() or public.is_staff());create policy topics_insert on public.topics for insert to authenticated with check(user_id=auth.uid() and status='pending');create policy topics_update on public.topics for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy answers_read on public.answers for select using(status='published' or user_id=auth.uid() or public.is_staff());create policy answers_insert_audience on public.answers for insert to authenticated with check(user_id=auth.uid() and status='pending' and exists(select 1 from topics t join profiles p on p.id=auth.uid() where t.id=topic_id and t.status='published' and (t.audience='all' or t.audience=p.gender)));create policy answers_update on public.answers for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy votes_read on public.answer_votes for select using(true);create policy votes_insert on public.answer_votes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from answers a where a.id=answer_id and a.user_id<>auth.uid()));create policy votes_delete on public.answer_votes for delete to authenticated using(user_id=auth.uid());
create policy bookmarks_own_read on public.topic_bookmarks for select to authenticated using(user_id=auth.uid());create policy bookmarks_own_insert on public.topic_bookmarks for insert to authenticated with check(user_id=auth.uid());create policy bookmarks_own_delete on public.topic_bookmarks for delete to authenticated using(user_id=auth.uid());
create index if not exists topics_feed_idx on public.topics(status,created_at desc);create index if not exists topics_audience_idx on public.topics(audience,created_at desc);create index if not exists topics_search_idx on public.topics using gin(to_tsvector('simple',title||' '||body));create index if not exists answers_topic_idx on public.answers(topic_id,created_at);

